+
+type columnDefinition struct {
+	label     string
+	content   interface{}
+	condition func(printContext) bool
+}
+
+type printContext struct {
+	withNamespace bool
+	withEvent     bool
+	wide          bool
+	columnLabels  []string
+}
+
+func vof(i interface{}) reflect.Value {
+	return reflect.ValueOf(i)
+}
+
+func getStringField(obj runtime.Object, name string) string {
+	return reflect.ValueOf(obj).Elem().FieldByName(name).String()
+}
+
+func getInterfaceField(obj runtime.Object, name string) interface{} {
+	return reflect.ValueOf(obj).Elem().FieldByName(name).Interface()
+}
+
+func makeUpdateColumn(event *watch.EventType) columnDefinition {
+	return columnDefinition{
+		label:   "UPDATE",
+		content: func(c printContext) string { return eventToString(event) }}
+}
+
+func makeNameColumn(name string) columnDefinition {
+	return columnDefinition{
+		label:   name,
+		content: func(obj runtime.Object) string { return getStringField(obj, "Name") }}
+}
+
+var namespaceColumn = columnDefinition{
+	label:     "NAMESPACE",
+	content:   func(obj runtime.Object) string { return getStringField(obj, "Namespace") },
+	condition: func(c printContext) bool { return c.withNamespace }}
+
+var noNamespaceColumn = columnDefinition{
+	label:     "NAMESPACE",
+	content:   func(obj runtime.Object) error { return fmt.Errorf("Namespace not supported") },
+	condition: func(c printContext) bool { return c.withNamespace }}
+
+var ageColumn = columnDefinition{
+	label: "AGE",
+	content: func(obj runtime.Object) string {
+		return translateTimestamp(getInterfaceField(obj, "CreationTimestamp").(util.Time))
+	}}
+
+func makeLabelColumn(labelName string) columnDefinition {
+	splitLabelName := strings.Split(labelName, "/")
+	columnLabel := strings.ToUpper(splitLabelName[len(splitLabelName)-1])
+	return columnDefinition{
+		label: columnLabel,
+		content: func(obj runtime.Object) string {
+			labelsMap := reflect.ValueOf(obj).Elem().FieldByName("Labels")
+			val := labelsMap.MapIndex(vof(labelName))
+			if val.IsValid() {
+				return val.String()
+			} else {
+				return "<n/a>"
+			}
+		}}
+}
+
+var podColumnsFunc = []columnDefinition{
+	namespaceColumn,
+	makeNameColumn("NAME"),
+	{label: "READY", content: func(pod *api.Pod) string {
+		readyContainers := 0
+		for i := 0; i < len(pod.Status.ContainerStatuses); i++ {
+			container := pod.Status.ContainerStatuses[i]
+			if container.Ready && container.State.Running != nil {
+				readyContainers++
+			}
+		}
+		totalContainers := len(pod.Spec.Containers)
+		return fmt.Sprintf("%d/%d", readyContainers, totalContainers)
+	}},
+	{label: "STATUS", content: func(pod *api.Pod) string {
+		reason := string(pod.Status.Phase)
+		if pod.Status.Reason != "" {
+			reason = pod.Status.Reason
+		}
+		for i := len(pod.Status.ContainerStatuses) - 1; i >= 0; i-- {
+			container := pod.Status.ContainerStatuses[i]
+
+			if container.State.Waiting != nil && container.State.Waiting.Reason != "" {
+				reason = container.State.Waiting.Reason
+			} else if container.State.Terminated != nil && container.State.Terminated.Reason != "" {
+				reason = container.State.Terminated.Reason
+			} else if container.State.Terminated != nil && container.State.Terminated.Reason == "" {
+				if container.State.Terminated.Signal != 0 {
+					reason = fmt.Sprintf("Signal:%d", container.State.Terminated.Signal)
+				} else {
+					reason = fmt.Sprintf("ExitCode:%d", container.State.Terminated.ExitCode)
+				}
+			}
+		}
+		return reason
+	}},
+	{label: "RESTARTS", content: func(pod *api.Pod) string {
+		restarts := 0
+		for i := 0; i < len(pod.Status.ContainerStatuses); i++ {
+			restarts += pod.Status.ContainerStatuses[i].RestartCount
+		}
+		return fmt.Sprintf("%d", restarts)
+	}},
+	ageColumn,
+	{label: "NODE", content: func(pod *api.Pod) string { return pod.Spec.NodeName },
+		condition: func(c printContext) bool { return c.wide }},
+}
+
+var podTemplateColumnsFunc = []columnDefinition{
+	namespaceColumn,
+	makeNameColumn("TEMPLATE"),
+	{label: "CONTAINER(S)", content: func(pod *api.PodTemplate) []string {
+		result := []string{}
+		for _, container := range pod.Template.Spec.Containers {
+			result = append(result, container.Name)
+		}
+		return result
+	}},
+	{label: "IMAGE(S)", content: func(pod *api.PodTemplate) []string {
+		result := []string{}
+		for _, container := range pod.Template.Spec.Containers {
