+var serviceColumnsFunc = []columnDefinition{
+	namespaceColumn,
+	makeNameColumn("NAME"),
+	{label: "CLUSTER_IP", content: func(s *api.Service) string {
+		return s.Spec.ClusterIP
+	}},
+	{label: "EXTERNAL_IP", content: func(s *api.Service) string {
+		switch s.Spec.Type {
