comment_text:
ok... looks like what is actually allowed is the intersection of this list's initial value, and what is in registered.supportedVersions (or what is in `$KUBE_API_VERSIONS`, if specified)... which is computed in init(), ordered by whatever is specified in the registered package, and reassigned here.

It is pretty misleading to have an initial list and priority order that gets filtered and reordered in `init()`. I'd rather see something like:

```
// ExternalVersions lists all known external versions for this group from most preferred to least preferred
var ExternalVersions []unversioned.GroupVersion

// Codec is the Codec for the most preferred ExternalVersion
var Codec runtime.Codec

...

func init() {
  validVersions := map[unversioned.GroupVersion]bool{v1.SchemeGroupVersion: true}

  for _, registeredVersion := range registered.GroupVersionsForGroup(api.SchemeGroupVersion.Group) {
    if !validVersions[registeredVersion] {
      panic(...)
    }
    ExternalVersions = append(ExternalVersions, registeredVersion)
  }

  if len(ExternalVersions) > 0 {
    Codec = runtime.CodecFor(api.Scheme, ExternalVersions[0].String())
    RESTMapper = newRESTMapper()
  }
}
```

