+type semanticRoles struct {
+	admin *rbac.ClusterRole
+	edit  *rbac.ClusterRole
+	view  *rbac.ClusterRole
+}
+
+func getSemanticRoles(roles []rbac.ClusterRole) semanticRoles {
+	ret := semanticRoles{}
+	for i := range roles {
+		role := roles[i]
+		switch role.Name {
+		case "admin":
+			ret.admin = &role
+		case "edit":
+			ret.edit = &role
+		case "view":
+			ret.view = &role
+		}
+	}
+	return ret
+}
