getGIDTable needs to be threadsafe, so guard gidTable with a lock, do a fast check under lock, build if needed, then do a follow up check under lock before returning

```
p.gidTableLock.Lock()
allocator, ok := p.gidTable[className]
p.gidTableLock.Unlock()
if ok {
  allocator.SetRange(min, max)
  return allocator, nil
}

// build, collect, set min/max ...
newAllocator := ... 

p.gidTableLock.Lock()
defer p.gidTableLock.Unlock()
// if one showed up since we last checked, use it
if allocator, ok := p.gidTable[className]; ok {
  allocator.SetRange(min, max)
  return allocator, nil
}
// otherwise, use the one we built
p.gidTable[className] = newAllocator
return newAllocator, nil
