pkg/apis/core/validation/validation.go:		if ip := net.ParseIP(hostAlias.IP); ip == nil {
pkg/apis/core/validation/validation.go:	ip := net.ParseIP(ipAddress)
pkg/apis/core/validation/validation.go:			if isIP := (net.ParseIP(ingress.IP) != nil); !isIP {
pkg/apis/core/validation/validation.go:			if isIP := (net.ParseIP(ingress.Hostname) != nil); isIP {
pkg/apis/core/validation/validation.go:	_, net, err := net.ParseCIDR(cidr)
pkg/apis/networking/validation/validation.go:			if isIP := (net.ParseIP(ih.Host) != nil); isIP {
pkg/proxy/apis/config/validation/validation.go:	if net.ParseIP(config.BindAddress) == nil {
pkg/proxy/apis/config/validation/validation.go:			if _, _, err := net.ParseCIDR(config.ClusterCIDR); err != nil {
pkg/proxy/apis/config/validation/validation.go:	if ip := net.ParseIP(hostIP); ip == nil {
pkg/proxy/apis/config/validation/validation.go:		if _, _, err := net.ParseCIDR(nodePortAddresses[i]); err != nil {
pkg/proxy/apis/config/validation/validation.go:		if _, _, err := net.ParseCIDR(excludeCIDRs[i]); err != nil {
staging/src/k8s.io/apimachinery/pkg/util/validation/validation.go:	if net.ParseIP(value) == nil {
staging/src/k8s.io/apimachinery/pkg/util/validation/validation.go:	ip := net.ParseIP(value)
